(()=>{
 const base=document.documentElement.dataset.base||'';
 if(base)document.querySelectorAll('a[href^="/"],img[src^="/"]').forEach(el=>{const attr=el.tagName==='IMG'?'src':'href';const v=el.getAttribute(attr);if(!v.startsWith('//')&&!v.startsWith(base+'/'))el.setAttribute(attr,base+v);});
 document.querySelector('.stt-mobile-menu')?.addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',on);document.querySelector('.stt-site-header').classList.toggle('stt-menu-open',on);});
 const gallery=document.querySelector('.stt-gallery'),lightbox=document.querySelector('.stt-lightbox');
 if(gallery&&lightbox){
  const thumbs=[...gallery.querySelectorAll('[data-stt-photo]')];let index=0;
  const show=i=>{index=(i+thumbs.length)%thumbs.length;const t=thumbs[index],image=t.querySelector('img');let src=t.dataset.sttPhoto;if(base&&src.startsWith('/')&&!src.startsWith(base+'/'))src=base+src;gallery.querySelector('.stt-main-photo').src=src;gallery.querySelector('.stt-main-photo').alt=image.alt;thumbs.forEach((x,j)=>x.setAttribute('aria-pressed',j===index));gallery.querySelector('.stt-photo-count').textContent=String(index+1).padStart(2,'0')+' / '+String(thumbs.length).padStart(2,'0');lightbox.querySelector('img').src=src;lightbox.querySelector('img').alt=image.alt;lightbox.querySelector('.stt-lightbox-count').textContent=(index+1)+' / '+thumbs.length;};
  thumbs.forEach((t,i)=>t.addEventListener('click',()=>show(i)));
  gallery.querySelector('.stt-gallery-open').addEventListener('click',()=>{show(index);lightbox.showModal();});
  lightbox.querySelector('[data-stt-prev]').addEventListener('click',()=>show(index-1));lightbox.querySelector('[data-stt-next]').addEventListener('click',()=>show(index+1));
  lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(index+1);if(e.key==='ArrowLeft')show(index-1);});
 }
 document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.stt-dialog-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
 const range=document.querySelector('#stt-shifts');
 range?.addEventListener('input',()=>{document.querySelector('#stt-shift-count').value=range.value;document.querySelector('#stt-calc-sum').textContent=new Intl.NumberFormat('ru-RU').format(Number(range.value)*Number(range.dataset.rate))+' ₽';});
 const source=document.querySelector('[data-stt-description-source]');
 if(source){const nodes=[...source.children];let items=nodes.filter(n=>n.matches('section.stt-seo-article,article.stt-seo-article'));if(!items.length)items=nodes.filter(n=>n.matches('p')&&n.textContent.trim()).map((p,i)=>{const a=document.createElement('article');a.className='stt-seo-article';a.dataset.seo=i+1;a.append(p);return a;});if(items.length){const frag=document.createDocumentFragment();for(let i=0;i<items.length;i+=2){const row=document.createElement('div');row.className='stt-article-pair';row.append(...items.slice(i,i+2));frag.append(row);if(i===0||i===2){const c=document.createElement('div');c.className='stt-inline-cta';const h=document.createElement('h3');h.textContent=i?'Уточним стоимость до выезда':'Обсудим вашу задачу';const a=document.createElement('a');a.className='stt-btn';a.href='#stt-request';a.textContent='Оставить заявку ↗';c.append(h,a);frag.append(c);}}const rest=nodes.filter(n=>!items.includes(n)&&n.parentNode===source);if(!nodes.every(n=>n.matches('p')))frag.append(...rest);source.replaceChildren(frag);}}
 const form=document.querySelector('.stt-inquiry'),review=document.querySelector('.stt-request-review');
 const date=form?.querySelector('[type="date"]');if(date){const now=new Date();date.min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');}
 form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form);const shifts=range?.value||'1';const text=`Заявка на аренду мини-экскаватора 7 тонн\nИмя: ${fd.get('name')}\nТелефон: ${fd.get('phone')}\nОбъект: ${fd.get('address')}\nДата: ${fd.get('date')}\nСмен: ${shifts}\nЗадача: ${fd.get('task')}\nПрошу уточнить наличие и стоимость с доставкой.`;review.querySelector('textarea').value=text;review.querySelector('[data-stt-email]').href='mailto:7416877@mail.ru?subject='+encodeURIComponent('Аренда мини-экскаватора 7 тонн')+'&body='+encodeURIComponent(text);review.querySelector('.stt-copy-status').textContent='';review.showModal();});
 document.querySelector('[data-stt-copy]')?.addEventListener('click',async()=>{const ta=review.querySelector('textarea');review.querySelector('[data-stt-email]').href='mailto:7416877@mail.ru?subject='+encodeURIComponent('Аренда мини-экскаватора 7 тонн')+'&body='+encodeURIComponent(ta.value);try{await navigator.clipboard.writeText(ta.value);review.querySelector('.stt-copy-status').textContent='Текст скопирован. Вставьте его в сообщение СТТ-Сервис.';}catch{ta.focus();ta.select();review.querySelector('.stt-copy-status').textContent='Выделен весь текст — скопируйте его вручную.'}});
 review?.querySelector('textarea').addEventListener('input',e=>{review.querySelector('[data-stt-email]').href='mailto:7416877@mail.ru?subject='+encodeURIComponent('Аренда мини-экскаватора 7 тонн')+'&body='+encodeURIComponent(e.target.value);});
})();
